const deviceKey = (device: Pick<DeviceSummary, "hostId" | "id">) =>
  `${device.hostId}\u0000${device.id}`;

export function DevicePanel(props: {
  readonly mode: PreviewPanelMode;
  readonly threadRef: ScopedThreadRef;
  readonly surface: Extract<RightPanelSurface, { kind: "device" }>;
  readonly visible: boolean;
  readonly onDismissSetup: () => void;
}) {
  const { environmentId, threadId } = props.threadRef;
  const gt = useGT();
  const { state, loaded, error: stateError, refresh: refreshState } = useDeviceState(environmentId);
  const list = useAtomCommand(deviceEnvironment.list, { reportFailure: false });
  const open = useAtomCommand(deviceEnvironment.open);
  const close = useAtomCommand(deviceEnvironment.close);
  // The panel stays mounted across thread switches, so an in-flight open or
  // power-off is tagged with the thread it belongs to and only shown there.
  const scope = `${environmentId}\u0000${threadId}`;
  const [operation, setOperation] = useState<{
    readonly scope: string;
    readonly pending: DeviceSummary | null;
    readonly error: string | null;
  } | null>(null);
  const pendingDevice = operation?.scope === scope ? operation.pending : null;
  const operationError = operation?.scope === scope ? operation.error : null;
  const pendingDeviceKey = pendingDevice ? deviceKey(pendingDevice) : null;

  const hostDisabled = state.hostStatus === "disabled";

  useAtomMount(
    props.visible && loaded && !hostDisabled
      ? deviceHostProbeAtom(environmentId)
      : NO_DEVICE_PROBE_ATOM,
  );

  const sessions = state.sessions.filter((session) => session.threadId === threadId);
  const activeSession = props.surface.target
    ? sessions.find(
        (session) =>
          session.deviceId === props.surface.target?.deviceId &&
          session.hostId === props.surface.target.hostId,
      )
    : undefined;
  const activeDevice = activeSession
    ? state.devices.find(
        (device) => device.hostId === activeSession.hostId && device.id === activeSession.deviceId,
      )
    : undefined;
  const activeHost = activeDevice
    ? state.hosts.find((host) => host.id === activeDevice.hostId)
    : undefined;

  const grouped = groupDevices(state);

  const startOperation = (pending: DeviceSummary | null) => {
    const started = { scope, pending, error: null };
    setOperation(started);
    // Returning to the same thread can start a newer operation before this one settles.
    return (error: string | null) =>
      setOperation((current) =>
        current === started ? { ...started, pending: null, error } : current,
      );
  };

  const selectDevice = async (value: string) => {
    const device = state.devices.find((candidate) => deviceKey(candidate) === value);
    if (!device) return;
    const settleOperation = startOperation(device);
    const result = await open({
      environmentId,
      input: {
        threadId,
        hostId: device.hostId,
        deviceId: device.id,
        platform: device.platform,
      },
    });
    if (result._tag === "Failure") settleOperation(formatEnvironmentQueryError(result.cause));
    else {
      // The server opened the device for the starting thread, so its tab opens there.
      useRightPanelStore.getState().openDevice(props.threadRef, {
        hostId: result.value.hostId,
        deviceId: result.value.deviceId,
        platform: device.platform,
        name: device.name,
      });
      settleOperation(null);
    }
  };

  const floatActive = () => {
    if (!activeDevice) return;
    usePreviewMiniPlayerStore.getState().open(props.threadRef, {
      kind: "device",
      hostId: activeDevice.hostId,
      deviceId: activeDevice.id,
      platform: activeDevice.platform,
      name: activeDevice.name,
    });
    useRightPanelStore.getState().close(props.threadRef);
  };

  const closeSurface = () => {
    const store = useRightPanelStore.getState();
    const { activeSurfaceId } = selectThreadRightPanelState(store.byThreadKey, props.threadRef);
    store.closeSurface(props.threadRef, props.surface.id);
    focusPanelTerminalAfterClose(props.threadRef, activeSurfaceId);
  };

  const closeActive = (powerOff: boolean) => {
    if (!activeSession) return;
    const settleOperation = startOperation(null);
    void close({
      environmentId,
      input: {
        threadId,
        hostId: activeSession.hostId,
        deviceId: activeSession.deviceId,
        shutdown: powerOff,
      },
    }).then((result) => {
      if (result._tag === "Failure") settleOperation(formatEnvironmentQueryError(result.cause));
      else closeSurface();
    });
  };

  const bootingDevices =
    state.bootingDevices?.filter((device) => device.threadId === threadId) ?? [];
  const { ready: hostReady, busy: hostBusy } = deviceHubReadiness(state);
  const loading = !activeDevice && (pendingDevice !== null || hostBusy || !loaded);
  // Without a first snapshot a failed subscription never settles on its own.
  const loadError = loaded ? null : stateError;
  const diagnostics = state.hosts.flatMap((host) => {
    const status = state.hostStatuses[host.id];
    const detail = status?.detail ?? (host.kind === "local" ? state.hostStatusDetail : undefined);
    return detail && (status?.status ?? state.hostStatus) === "ready"
      ? [
          {
            hostId: host.id,
            label: host.label,
            detail,
            incompletePlatforms: incompleteListings(status),
          },
        ]
      : [];
  });
  const unavailablePlatforms = state.hosts.flatMap((host) =>
    host.platforms
      .filter((platform) => !platform.available)
      .map((platform) => ({ ...platform, hostId: host.id, hostLabel: host.label })),
  );

  if (loaded && (!state.onboardingCompleted || hostDisabled)) {
    return (
      <Dialog
        open={props.visible}
        onOpenChange={(isOpen) => {
          if (!isOpen) props.onDismissSetup();
        }}
      >
        <WizardPopup>
          <DeviceSetup environmentId={environmentId} state={state} />
        </WizardPopup>
      </Dialog>
    );
  }

  return (
    <PreviewPanelShell mode={props.mode}>
      <div className="relative flex min-h-0 flex-1 flex-col">
        <div
          className={cn(
            "shrink-0 bg-background",
            loading && "absolute inset-x-0 top-0 z-10 max-h-[40%] overflow-y-auto",
          )}
        >
          <div hidden={!!activeDevice}>
            {diagnostics.map((diagnostic) => (
              <DeviceDiscoveryWarning
                key={`${environmentId}\u0000${diagnostic.hostId}`}
                label={diagnostic.label}
                detail={diagnostic.detail}
                incompletePlatforms={diagnostic.incompletePlatforms}
                onRetry={() => list({ environmentId, input: {} })}
              />
            ))}
          </div>
          <DeviceHostUpdates state={state} environmentId={environmentId} />
          {bootingDevices.length > 0 ? (
            <div role="status" className="border-b px-3 py-2 text-xs text-muted-foreground">
              <T>
                Starting <Var>{bootingDevices.map((device) => device.name).join(", ")}</Var>… This
                can take a minute.
              </T>
            </div>
          ) : null}
          {operationError ? (
            <DeviceNotice onDismiss={() => setOperation(null)}>{operationError}</DeviceNotice>
          ) : null}
        </div>
        <div className="@container relative flex min-h-0 flex-1">
          {activeDevice && activeSession ? (
            <DeviceWorkspace
              key={`${environmentId}\u0000${deviceKey(activeDevice)}`}
              environmentId={environmentId}
              device={activeDevice}
              hostLabel={activeHost?.label ?? gt("Device host")}
              hostKind={activeHost?.kind}
              hostDiagnostics={
                diagnostics.find(({ hostId }) => hostId === activeDevice.hostId)?.detail
              }
              visible={props.visible}
              onFloat={floatActive}
              onClose={closeSurface}
              onDisconnect={() => closeActive(false)}
              onPowerOff={() => closeActive(true)}
            />
          ) : loading ? (
            <DeviceLoadingView
              name={pendingDevice?.name ?? gt("Devices")}
              description={
                pendingDevice
                  ? `${state.hosts.find((host) => host.id === pendingDevice.hostId)?.label ?? gt("Device host")} · ${pendingDevice.version}`
                  : ""
              }
              stage="opening"
              message={
                loadError ??
                (pendingDevice
                  ? pendingDevice.booted
                    ? gt("Opening device…")
                    : gt("Starting device…")
                  : state.hostStatus === "installing"
                    ? (state.hostStatusDetail ?? gt("Installing device support…"))
                    : gt("Finding devices…"))
              }
              error={loadError !== null}
            >
              {loadError !== null ? (
                <Button size="sm" variant="outline" onClick={refreshState}>
                  <T>Retry</T>
                </Button>
              ) : null}
            </DeviceLoadingView>
          ) : (
            <div className="scrollbar-gutter-both flex size-full flex-col overflow-y-auto px-5 py-8 text-sm text-muted-foreground">
              <div
                className={cn(
                  "mx-auto flex w-full max-w-xl flex-col gap-6",
                  grouped.length === 0 && "my-auto items-center text-center",
                )}
              >
                {grouped.length === 0 ? (
                  <>
                    <Smartphone className="size-6 opacity-60" />
                    <p
                      className="max-h-32 w-full max-w-sm overflow-y-auto whitespace-pre-line break-words"
                      tabIndex={state.hostStatus === "failed" ? 0 : undefined}
                    >
                      {state.hostStatus === "failed"
                        ? (state.hostStatusDetail ?? gt("The device hub failed to start."))
                        : gt("No simulators or emulators were found on this environment.")}
                    </p>
                  </>
                ) : null}
                {hostReady && grouped.length > 0 ? (
                  <div className="w-full space-y-6 text-left">
                    {grouped.map((group) => (
                      <section key={group.platform} className="space-y-3">
                        <div className="flex items-center gap-2 text-sm text-muted-foreground">
                          <Smartphone className="size-4 shrink-0" />
                          <h3 className="font-medium">
                            {group.platform === "ios"
                              ? gt("iOS Simulators")
                              : gt("Android Emulators")}
                          </h3>
                        </div>
                        <DiscoveryList>
                          {group.devices.map((device) => (
                            <div
                              key={deviceKey(device)}
                              className="flex items-center gap-3 px-3 py-3"
                            >
                              <span className="grid size-8 shrink-0 place-items-center rounded-md border border-border/60">
                                <Smartphone className="size-4" />
                              </span>
                              <div className="flex min-w-0 flex-1 flex-col">
                                <span className="truncate text-sm font-medium text-foreground">
                                  {device.name}
                                </span>
                                <span className="truncate text-xs text-muted-foreground">
                                  {`${state.hosts.find((host) => host.id === device.hostId)?.label} · ${device.version} · ${device.booted ? gt("Running", { $context: "device state" }) : gt("Stopped", { $context: "device state" })}`}
                                </span>
                              </div>
                              <Button
                                variant="outline"
                                size="sm"
                                disabled={pendingDeviceKey !== null}
                                aria-label={
                                  device.booted
                                    ? gt("Open {name}", { name: device.name })
                                    : gt("Start {name}", { name: device.name })
                                }
                                onClick={() => void selectDevice(deviceKey(device))}
                              >
                                {pendingDeviceKey === deviceKey(device) ? (
                                  <Spinner size="xs" />
                                ) : device.booted ? (
                                  <ArrowUpRight />
                                ) : (
                                  <Play />
                                )}
                                {device.booted
                                  ? gt("Open", { $context: "verb, opens a running device" })
                                  : gt("Start", { $context: "verb, boots a device" })}
                              </Button>
                            </div>
                          ))}
                        </DiscoveryList>
                      </section>
                    ))}
                  </div>
                ) : null}
                {hostReady &&
                !isAndroidDiscoveryUncertain(state) &&
                !state.devices.some((device) => device.platform === "android") &&
                !unavailablePlatforms.some((platform) => platform.platform === "android") ? (
                  <p className="max-w-sm text-xs">
                    <T>
                      No Android virtual devices found. Create one in Android Studio's Device
                      Manager, then refresh.
                    </T>
                  </p>
                ) : null}
                {loaded && !hostBusy ? (
                  <Button
                    className={grouped.length > 0 ? "self-start" : "self-center"}
                    variant="outline"
                    size="sm"
                    onClick={() => void list({ environmentId, input: {} })}
                  >
                    <T>Refresh devices</T>
                  </Button>
                ) : null}
              </div>
            </div>
          )}
        </div>
      </div>
    </PreviewPanelShell>
  );
}

function DeviceNotice(props: { readonly onDismiss: () => void; readonly children: ReactNode }) {
  const gt = useGT();
  return (
    <div
      role="alert"
      className="flex items-start gap-2 border-b bg-destructive/5 px-3 py-2 text-xs text-destructive"
    >
      <CircleAlert className="mt-1 size-3.5 shrink-0" />
      <div
        className="max-h-32 min-w-0 flex-1 overflow-y-auto whitespace-pre-wrap break-words"
        tabIndex={0}
      >
        {props.children}
      </div>
      <Button
        size="icon-xs"
        variant="ghost"
        aria-label={gt("Dismiss device error")}
        onClick={props.onDismiss}
      >
        <X />
      </Button>
    </div>
  );
}

function DeviceDiscoveryWarning(props: {
  readonly label: string;
  readonly detail: string;
  readonly incompletePlatforms: readonly DevicePlatform[];
  readonly onRetry: () => Promise<unknown>;
}) {
  const gt = useGT();
  const [open, setOpen] = useState(false);
  const [retrying, setRetrying] = useState(false);
  const [dismissedCause, setDismissedCause] = useState<string | null>(null);
  const cause = `${props.incompletePlatforms.join()}\u0000${props.detail}`;
  // A dismissal hides one occurrence; a cause that returns later shows again.
  if (dismissedCause !== null && dismissedCause !== cause) setDismissedCause(null);
  if (dismissedCause === cause) return null;
  const platforms = props.incompletePlatforms.map((platform) =>
    platform === "ios" ? "iOS" : "Android",
  );
  return (
    <div
      role="status"
      className="flex flex-wrap items-center gap-x-2 gap-y-0.5 border-b px-3 py-1 text-xs text-muted-foreground"
    >
      <span className="flex min-w-0 flex-1 basis-56 items-start gap-2">
        <CircleAlert className="mt-px size-3.5 shrink-0 text-warning-foreground" />
        <span className="min-w-0">
          {platforms.length > 1
            ? gt("{first} and {second} lists on {host} may be incomplete.", {
                first: platforms[0],
                second: platforms[1],
                host: props.label,
              })
            : platforms.length === 1
              ? gt("{platform} list on {host} may be incomplete.", {
                  platform: platforms[0],
                  host: props.label,
                })
              : gt("Device discovery on {host} reported a warning.", { host: props.label })}
        </span>
      </span>
      <span className="ml-auto flex shrink-0 items-center gap-0.5">
        {platforms.length > 0 ? (
          <Button
            size="micro"
            variant="ghost"
            disabled={retrying}
            aria-label={gt("Retry device discovery on {host}", { host: props.label })}
            onClick={() => {
              setRetrying(true);
              void props.onRetry().finally(() => setRetrying(false));
            }}
          >
            {retrying ? gt("Retrying…") : gt("Retry")}
          </Button>
        ) : null}
        <Popover open={open} onOpenChange={setOpen}>
          <PopoverTrigger
            aria-label={gt("Details for {host}", { host: props.label })}
            render={<Button size="micro" variant="ghost" />}
          >
            <T>Details</T>
          </PopoverTrigger>
          <PopoverPopup side="bottom" align="end" width="lg" padding="compact">
            <p className="whitespace-pre-wrap break-words font-mono text-xs text-muted-foreground">
              {props.detail}
            </p>
          </PopoverPopup>
        </Popover>
        <Button
          size="icon-micro"
          variant="ghost"
          aria-label={gt("Dismiss device warning for {host}", { host: props.label })}
          onClick={() => {
            setOpen(false);
            setDismissedCause(cause);
          }}
        >
          <X />
        </Button>
      </span>
    </div>
  );
}

function groupDevices(state: DeviceServiceState) {
  const groups: Array<{ platform: DevicePlatform; devices: DeviceSummary[] }> = [];
  for (const platform of ["ios", "android"] as const) {
    const devices = state.devices
      .filter((device) => device.platform === platform)
      .toSorted((a, b) => Number(b.booted) - Number(a.booted) || a.name.localeCompare(b.name));
    if (devices.length > 0) groups.push({ platform, devices });
  }
  return groups;
}

import { thrownErrorMessage } from "@t3tools/client-runtime/errors";
import { m } from "~/i18n/messages";
import * as Schema from "effect/Schema";
import type { DeviceHostSummary, DeviceSummary, EnvironmentId } from "@t3tools/contracts";
import { useGT } from "gt-react";
import { useRef, useState } from "react";
import {
  captureDeviceScreenshot,
  DeviceScreenshotError,
} from "@t3tools/client-runtime/device/screenshot";
import { refreshDeviceHubAccess, useDeviceHubAccess } from "~/state/device";
import { DeviceControlsRail } from "./DeviceControlsRail";
import { DeviceStreamView } from "./DeviceStreamView";
import { DeviceToolsPanel } from "./DeviceToolsPanel";
import { useDeviceControls } from "./useDeviceControls";

const isDeviceScreenshotError = Schema.is(DeviceScreenshotError);

const DOWNLOAD_URL_LIFETIME_MS = 60_000;

export function DeviceWorkspace(props: {
  environmentId: EnvironmentId;
  device: DeviceSummary;
  hostLabel: string;
  hostKind: DeviceHostSummary["kind"] | undefined;
  hostDiagnostics: string | undefined;
  visible: boolean;
  onFloat: () => void;
  onClose: () => void;
  onDisconnect: () => void;
  onPowerOff: () => void;
}) {
  const gt = useGT();
  const [toolsOpen, setToolsOpen] = useState(false);
  const [axOverlay, setAxOverlay] = useState(false);
  const [screenshotPending, setScreenshotPending] = useState(false);
  const [screenshotError, setScreenshotError] = useState<string | null>(null);
  // A capture always finishes, even if the panel hides or closes meanwhile; the user asked for it.
  const capturing = useRef(false);
  const access = useDeviceHubAccess(props.environmentId, props.device.hostId);
  // Settings and tools run commands on the device's own machine, which Expo and Simlock do not expose.
  const runsHostCommands = props.hostKind === "local" || props.hostKind === "ssh";
  const controls = useDeviceControls({
    ...props,
    access,
    visible: props.visible && runsHostCommands,
  });
  const saveScreenshot = () => {
    if (!access || capturing.current || !props.visible) return;
    capturing.current = true;
    setScreenshotPending(true);
    setScreenshotError(null);
    return captureDeviceScreenshot(
      { access, platform: props.device.platform, deviceId: props.device.id },
      // Never aborted: see `capturing` above.
      new AbortController().signal,
    )
      .then((image) => {
        const url = URL.createObjectURL(image);
        const link = document.createElement("a");
        link.href = url;
        link.download = `${props.device.name.replace(/[^a-z0-9-]/gi, "-")}-${Date.now()}.png`;
        document.body.append(link);
        link.click();
        link.remove();
        // The browser reads the blob after the click returns.
        window.setTimeout(() => URL.revokeObjectURL(url), DOWNLOAD_URL_LIFETIME_MS);
      })
      .catch((cause: unknown) => {
        if (isDeviceScreenshotError(cause) && cause.status === 401)
          refreshDeviceHubAccess(props.environmentId);
        setScreenshotError(
          thrownErrorMessage(cause, m) ?? gt("Screenshot capture failed. Try again."),
        );
      })
      .finally(() => {
        capturing.current = false;
        setScreenshotPending(false);
      });
  };
  return (
    <>
      <div className="relative flex min-h-0 min-w-0 flex-1 flex-col">
        {screenshotError || (controls.error && !toolsOpen) ? (
          <p role="alert" className="px-3 py-2 text-xs text-destructive">
            {screenshotError ?? controls.error}
          </p>
        ) : null}
        <div className="min-h-0 flex-1">
          <DeviceStreamView
            environmentId={props.environmentId}
            platform={props.device.platform}
            deviceName={props.device.name}
            deviceDescription={`${props.hostLabel} · ${props.device.version}`}
            deviceId={props.device.id}
            hostId={props.device.hostId}
            visible={props.visible}
            serveSimOnly={props.hostKind === "simlock"}
            axOverlay={axOverlay}
            allowPhoneView
            renderControls={(view) => (
              <DeviceControlsRail
                platform={props.device.platform}
                hostKind={props.hostKind}
                handle={view.handle}
                view={view}
                controls={controls}
                screenshotPending={screenshotPending}
                onScreenshot={() => void saveScreenshot()}
                toolsOpen={toolsOpen}
                onTools={() => setToolsOpen(!toolsOpen)}
                onFloat={props.onFloat}
                onClose={props.onClose}
                onDisconnect={props.onDisconnect}
                onPowerOff={props.onPowerOff}
              />
            )}
          />
        </div>
      </div>
      {toolsOpen ? (
        <DeviceToolsPanel
          device={props.device}
          controls={controls}
          hostDiagnostics={props.hostDiagnostics}
          access={access}
          axOverlay={axOverlay}
          onAxOverlayChange={setAxOverlay}
          onClose={() => setToolsOpen(false)}
          className="absolute inset-y-0 right-0 z-10 w-full max-w-72 border-l shadow-lg @[700px]:static @[700px]:w-72 @[700px]:shrink-0 @[700px]:shadow-none"
        />
      ) : null}
    </>
  );
}
